import operator
from collections import OrderedDict
from collections.abc import MutableSequence

from ..hdl import MemoryIdentity, MemoryInstance, Shape, ShapeCastable, Const
from ..hdl._mem import MemorySimRead
from ..utils import ceil_log2
from .data import ArrayLayout
from . import wiring
from .. import tracer


__all__ = ["WritePort", "ReadPort", "Memory", "FrozenError"]


class WritePort:
    """A memory write port.

    Parameters
    ----------
    signature : :class:`WritePort.Signature`
        The signature of the port.
    memory : :class:`Memory` or ``None``
        Memory associated with the port.
    domain : str
        Clock domain. Defaults to ``"sync"``. Writes have a latency of 1 clock cycle.

    Attributes
    ----------
    signature : :class:`WritePort.Signature`
    memory : :class:`Memory`
    domain : str
    """

    class Signature(wiring.Signature):
        """A signature of a write port.

        Parameters
        ----------
        addr_width : int
            Address width in bits. If the port is associated with a :class:`Memory`,
            it must be equal to :py:`ceil_log2(memory.depth)`.
        shape : :ref:`shape-like <lang-shapelike>` object
            The shape of the port data. If the port is associated with a :class:`Memory`,
            it must be equal to its element shape.
        granularity : int or ``None``
            Port granularity. If ``None``, the entire storage element is written at once.
            Otherwise, determines the size of access covered by a single bit of ``en``.
            One of the following must hold:

            - ``granularity is None``, in which case ``en_width == 1``, or
            - ``shape == unsigned(data_width)`` and ``data_width == 0 or data_width % granularity == 0`` in which case ``en_width == data_width // granularity`` (or 0 if ``data_width == 0``)
            - ``shape == amaranth.lib.data.ArrayLayout(_, elem_count)`` and ``elem_count == 0 or elem_count % granularity == 0`` in which case ``en_width == elem_count // granularity`` (or 0 if ``elem_count == 0``)

        Members
        -------
        addr: :py:`unsigned(data_width)`
        data: ``shape``
        en: :py:`unsigned(en_width)`
        """

        def __init__(self, *, addr_width, shape, granularity=None):
            if not isinstance(addr_width, int) or addr_width < 0:
                raise TypeError(f"`addr_width` must be a non-negative integer, not {addr_width!r}")
            self._addr_width = addr_width
            self._shape = shape
            self._granularity = granularity
            if granularity is None:
                en_width = 1
            elif not isinstance(granularity, int) or granularity < 0:
                raise TypeError(f"Granularity must be a non-negative int or None, not {granularity!r}")
            elif not isinstance(shape, ShapeCastable):
                actual_shape = Shape.cast(shape)
                if actual_shape.signed:
                    raise ValueError("Granularity cannot be specified with signed shape")
                elif actual_shape.width == 0:
                    en_width = 0
                elif granularity == 0:
                    raise ValueError("Granularity must be positive")
                elif actual_shape.width % granularity != 0:
                    raise ValueError("Granularity must divide data width")
                else:
                    en_width = actual_shape.width // granularity
            elif isinstance(shape, ArrayLayout):
                if shape.length == 0:
                    en_width = 0
                elif granularity == 0:
                    raise ValueError("Granularity must be positive")
                elif shape.length % granularity != 0:
                    raise ValueError("Granularity must divide data array length")
                else:
                    en_width = shape.length // granularity
            else:
                raise TypeError("Granularity can only be specified for plain unsigned `Shape` or `ArrayLayout`")
            super().__init__({
                "addr": wiring.In(addr_width),
                "data": wiring.In(shape),
                "en": wiring.In(en_width),
            })

        def create(self, *, path=None, src_loc_at=0):
            return WritePort(self, memory=None, domain="sync", path=path, src_loc_at=1 + src_loc_at)

        @property
        def addr_width(self):
            return self._addr_width

        @property
        def shape(self):
            return self._shape

        @property
        def granularity(self):
            return self._granularity

        def __eq__(self, other):
            return (type(self) is type(other) and
                    self.addr_width == other.addr_width and
                    self.shape == other.shape and
                    self.granularity == other.granularity)

        def __repr__(self):
            granularity = f", granularity={self.granularity}" if self.granularity is not None else ""
            return f"WritePort.Signature(addr_width={self.addr_width}, shape={self.shape}{granularity})"


    def __init__(self, signature, *, memory, domain, path=None, src_loc_at=0):
        if not isinstance(signature, WritePort.Signature):
            raise TypeError(f"Expected `WritePort.Signature`, not {signature!r}")
        if memory is not None:
            if not isinstance(memory, Memory):
                raise TypeError(f"Expected `Memory` or `None`, not {memory!r}")
            if signature.shape != memory.shape or Shape.cast(signature.shape) != Shape.cast(memory.shape):
                raise ValueError(f"Memory shape {memory.shape!r} doesn't match port shape {signature.shape!r}")
            if signature.addr_width != ceil_log2(memory.depth):
                raise ValueError(f"Memory address width {ceil_log2(memory.depth)!r} doesn't match port address width {signature.addr_width!r}")
        if not isinstance(domain, str):
            raise TypeError(f"Domain has to be a string, not {domain!r}")
        if domain == "comb":
            raise ValueError("Write port domain cannot be \"comb\"")
        self._signature = signature
        self._memory = memory
        self._domain = domain
        self.__dict__.update(signature.members.create(path=path, src_loc_at=1 + src_loc_at))
        if memory is not None:
            memory._w_ports.append(self)

    @property
    def signature(self):
        return self._signature

    @property
    def memory(self):
        return self._memory

    @property
    def domain(self):
        return self._domain


class ReadPort:
    """A memory read port.

    Parameters
    ----------
    signature : :class:`ReadPort.Signature`
        The signature of the port.
    memory : :class:`Memory`
        Memory associated with the port.
    domain : str
        Clock domain. Defaults to ``"sync"``. If set to ``"comb"``, the port is asynchronous.
        Otherwise, the read data becomes available on the next clock cycle.
    transparent_for : iterable of :class:`WritePort`
        The set of write ports that this read port should be transparent with. All ports
        must belong to the same memory and the same clock domain.

    Attributes
    ----------
    signature : :class:`ReadPort.Signature`
    memory : :class:`Memory`
    domain : str
    transparent_for : tuple of :class:`WritePort`
    """

    class Signature(wiring.Signature):
        """A signature of a read port.

        Parameters
        ----------
        addr_width : int
            Address width in bits. If the port is associated with a :class:`Memory`,
            it must be equal to :py:`ceil_log2(memory.depth)`.
        shape : :ref:`shape-like <lang-shapelike>` object
            The shape of the port data. If the port is associated with a :class:`Memory`,
            it must be equal to its element shape.

        Members
        -------
        addr: :py:`unsigned(data_width)`
        data: ``shape``
        en: :py:`unsigned(1)`
            The enable signal. If ``domain == "comb"``, this is tied to ``Const(1)``.
            Otherwise it is a signal with ``init=1``.
        """

        def __init__(self, *, addr_width, shape):
            if not isinstance(addr_width, int) or addr_width < 0:
                raise TypeError(f"`addr_width` must be a non-negative integer, not {addr_width!r}")
            self._addr_width = addr_width
            self._shape = shape
            super().__init__({
                "addr": wiring.In(addr_width),
                "data": wiring.Out(shape),
                "en": wiring.In(1, init=1),
            })

        def create(self, *, path=None, src_loc_at=0):
            return ReadPort(self, memory=None, domain="sync", path=path, src_loc_at=1 + src_loc_at)

        @property
        def addr_width(self):
            return self._addr_width

        @property
        def shape(self):
            return self._shape

        def __eq__(self, other):
            return (type(self) is type(other) and
                    self.addr_width == other.addr_width and
                    self.shape == other.shape)

        def __repr__(self):
            return f"ReadPort.Signature(addr_width={self.addr_width}, shape={self.shape})"


    def __init__(self, signature, *, memory, domain, transparent_for=(), path=None, src_loc_at=0):
        if not isinstance(signature, ReadPort.Signature):
            raise TypeError(f"Expected `ReadPort.Signature`, not {signature!r}")
        if memory is not None:
            if not isinstance(memory, Memory):
                raise TypeError(f"Expected `Memory` or `None`, not {memory!r}")
            if signature.shape != memory.shape or Shape.cast(signature.shape) != Shape.cast(memory.shape):
                raise ValueError(f"Memory shape {memory.shape!r} doesn't match port shape {signature.shape!r}")
            if signature.addr_width != ceil_log2(memory.depth):
                raise ValueError(f"Memory address width {ceil_log2(memory.depth)!r} doesn't match port address width {signature.addr_width!r}")
        if not isinstance(domain, str):
            raise TypeError(f"Domain has to be a string, not {domain!r}")
        transparent_for = tuple(transparent_for)
        for port in transparent_for:
            if not isinstance(port, WritePort):
                raise TypeError("`transparent_for` must contain only `WritePort` instances")
            if memory is not None and port not in memory._w_ports:
                raise ValueError("Transparent write ports must belong to the same memory")
            if port.domain != domain:
                raise ValueError("Transparent write ports must belong to the same domain")
        self._signature = signature
        self._memory = memory
        self._domain = domain
        self._transparent_for = transparent_for
        self.__dict__.update(signature.members.create(path=path, src_loc_at=1 + src_loc_at))
        if domain == "comb":
            self.en = Const(1)
        if memory is not None:
            memory._r_ports.append(self)

    @property
    def signature(self):
        return self._signature

    @property
    def memory(self):
        return self._memory

    @property
    def domain(self):
        return self._domain

    @property
    def transparent_for(self):
        return self._transparent_for


class FrozenError(Exception):
    """Raised when trying to modify a frozen memory.

    This exception is raised when attempting to modify a memory that has already been
    elaborated and is therefore frozen. This typically happens when trying to add ports
    or modify the initialization data of a memory after it has been elaborated.
    """


class Memory(wiring.Component):
    """A word addressable storage.

    Parameters
    ----------
    shape : :ref:`shape-like <lang-shapelike>` object
        The shape of a single element of the storage.
    depth : int
        Word count. This memory contains ``depth`` storage elements.
    init : iterable of int or of any objects accepted by ``shape.const()``
        Initial values. At power on, each storage element in this memory is initialized to
        the corresponding element of ``init``, if any, or to the default value of ``shape`` otherwise.
        Uninitialized memories are not currently supported.
    attrs : dict
        Dictionary of synthesis attributes.

    Attributes
    ----------
    shape : :ref:`shape-like <lang-shapelike>`
    depth : int
    init : :class:`Memory.Init`
    attrs : dict
    r_ports : tuple of :class:`ReadPort`
    w_ports : tuple of :class:`WritePort`
    """

    class Init(MutableSequence):
        """Initial data of a :class:`Memory`.

        This is a container implementing the ``MutableSequence`` protocol, enforcing two constraints:

        - the length is immutable and must equal ``depth``
        - if ``shape`` is a :class:`ShapeCastable`, each element can be cast to ``shape`` via :py:`shape.const()`
        - otherwise, each element is an :py:`int`
        """
        def __init__(self, items, *, shape, depth):
            Shape.cast(shape)
            if not isinstance(depth, int) or depth < 0:
                raise TypeError("Memory depth must be a non-negative integer, not {!r}"
                                .format(depth))
            self._shape = shape
            self._depth = depth

            # Handle MemoryData.Init objects
            if hasattr(items, '__class__') and hasattr(items, '_data'):
                # Check if it's a MemoryData.Init object by checking class name
                if hasattr(items.__class__, '__name__') and items.__class__.__name__ == 'Init':
                    items = items._data

            if isinstance(shape, ShapeCastable):
                self._items = [None] * depth
                default = Const.cast(shape.const(None)).value
                self._raw = [default] * depth
            else:
                self._raw = self._items = [0] * depth
            try:
                for idx, item in enumerate(items):
                    self[idx] = item
            except (TypeError, ValueError) as e:
                raise type(e)("Memory initialization value at address {:x}: {}"
                                .format(idx, e)) from None

        def __getitem__(self, index):
            return self._items[index]

        def __setitem__(self, index, value):
            if isinstance(index, slice):
                start, stop, step = index.indices(len(self._items))
                indices = range(start, stop, step)
                if len(value) != len(indices):
                    raise ValueError("Changing length of Memory.init is not allowed")
                for actual_index, actual_value in zip(indices, value):
                    self[actual_index] = actual_value
            else:
                if isinstance(self._shape, ShapeCastable):
                    self._raw[index] = Const.cast(self._shape.const(value)).value
                else:
                    value = operator.index(value)
                self._items[index] = value

        def __delitem__(self, index):
            raise TypeError("Deleting items from Memory.init is not allowed")

        def insert(self, index, value):
            raise TypeError("Inserting items into Memory.init is not allowed")

        def __len__(self):
            return self._depth

        @property
        def depth(self):
            return self._depth

        @property
        def shape(self):
            return self._shape

        def __repr__(self):
            return f"Memory.Init({self._items!r})"

    def __init__(self, *, depth, shape, init, attrs=None, src_loc_at=0, src_loc=None):
        # shape and depth validation performed in Memory.Init constructor.
        if shape is None:
            raise TypeError("Memory requires a 'shape' parameter")
        self._depth = depth
        self._shape = shape
        self._init = Memory.Init(init, shape=shape, depth=depth)
        self._attrs = {} if attrs is None else dict(attrs)
        self.src_loc = src_loc or tracer.get_src_loc(src_loc_at=src_loc_at)
        self._identity = MemoryIdentity()
        self._r_ports: "list[ReadPort]" = []
        self._w_ports: "list[WritePort]" = []
        super().__init__(wiring.Signature({}))

    def read_port(self, *, domain="sync", transparent_for=()):
        """Adds a new read port and returns it.

        Equivalent to creating a :class:`ReadPort` with a signature of :py:`ReadPort.Signature(addr_width=ceil_log2(self.depth), shape=self.shape)`
        """
        signature = ReadPort.Signature(addr_width=ceil_log2(self.depth), shape=self.shape)
        return ReadPort(signature, memory=self, domain=domain, transparent_for=transparent_for)

    def write_port(self, *, domain="sync", granularity=None):
        """Adds a new write port and returns it.

        Equivalent to creating a :class:`WritePort` with a signature of :py:`WritePort.Signature(addr_width=ceil_log2(self.depth), shape=self.shape, granularity=granularity)`
        """
        signature = WritePort.Signature(addr_width=ceil_log2(self.depth), shape=self.shape, granularity=granularity)
        return WritePort(signature, memory=self, domain=domain)

    @property
    def depth(self):
        return self._depth

    @property
    def shape(self):
        return self._shape

    @property
    def init(self):
        return self._init

    @init.setter
    def init(self, init):
        self._init = Memory.Init(init, shape=self._shape, depth=self._depth)

    @property
    def attrs(self):
        return self._attrs

    @property
    def w_ports(self):
        """Returns a tuple of all write ports defined so far."""
        return tuple(self._w_ports)

    @property
    def r_ports(self):
        """Returns a tuple of all read ports defined so far."""
        return tuple(self._r_ports)

    @property
    def read_ports(self):
        """Returns a tuple of all read ports defined so far."""
        return self.r_ports

    @property
    def w_ports(self):
        """Returns a tuple of all write ports defined so far."""
        return tuple(self._w_ports)

    @property
    def write_ports(self):
        """Returns a tuple of all write ports defined so far."""
        return self.w_ports

    def elaborate(self, platform):
        if hasattr(platform, "get_memory"):
            return platform.get_memory(self)
        shape = Shape.cast(self.shape)
        instance = MemoryInstance(identity=self._identity, width=shape.width, depth=self.depth, init=self.init._raw, attrs=self.attrs, src_loc=self.src_loc)
        w_ports = {}
        for port in self._w_ports:
            idx = instance.write_port(domain=port.domain, addr=port.addr, data=port.data, en=port.en)
            w_ports[port] = idx
        for port in self._r_ports:
            transparent_for = [w_ports[write_port] for write_port in port.transparent_for]
            instance.read_port(domain=port.domain, data=port.data, addr=port.addr, en=port.en, transparent_for=transparent_for)
        return instance

    def __getitem__(self, index):
        """Simulation only."""
        return MemorySimRead(self._identity, index)

from typing import Tuple
from collections import defaultdict, OrderedDict
import enum
import warnings

from .._utils import flatten
from .. import tracer, _unused
from . import _ast, _cd, _ir, _nir


__all__ = [
    "UnusedElaboratable", "Elaboratable", "DriverConflict", "Fragment", "Instance",
    "IOBufferInstance", "PortDirection", "Design", "build_netlist",
]


class UnusedElaboratable(_unused.UnusedMustUse):
    # The warning is initially silenced. If everything that has been constructed remains unused,
    # it means the application likely crashed (with an exception, or in another way that does not
    # call `sys.excepthook`), and it's not necessary to show any warnings.
    # Once elaboration starts, the warning is enabled.
    _MustUse__silence = True


class Elaboratable(_unused.MustUse):
    _MustUse__warning = UnusedElaboratable


class DriverConflict(UserWarning):
    pass


class DuplicateElaboratable(Exception):
    """Raised when the same elaboratable is included multiple times in the hierarchy.

    This exception is raised when an elaboratable object is added to a design more than once,
    which creates a duplicate in the hierarchy. This typically occurs when the same
    Module instance is added as a submodule multiple times.
    """


class SwitchValue:
    """A switch value expression for conditional assignment.

    This class represents a switch value expression that evaluates to one of several
    possible values based on a condition. It's used for generating conditional assignments
    in the netlist.
    """

    def __init__(self, test, cases):
        self.test = test
        self.cases = cases

    def eq(self, value):
        # Return an assignment statement
        from ._ast import Assign
        return Assign(self, value)

    def __repr__(self):
        return f"SwitchValue({self.test!r}, {self.cases!r})"


class DuplicateElaboratable(Exception):
    """Raised when the same elaboratable is included multiple times in the hierarchy.

    This exception is raised when an elaboratable object is added to a design more than once,
    which creates a duplicate in the hierarchy. This typically occurs when the same
    Module instance is added as a submodule multiple times.
    """


class Fragment:
    @staticmethod
    def get(obj, platform):
        code = None
        origins = []
        while True:
            if isinstance(obj, Fragment):
                if hasattr(obj, "origins"):
                    obj.origins = tuple(origins)
                return obj
            elif isinstance(obj, Elaboratable):
                code = obj.elaborate.__code__
                UnusedElaboratable._MustUse__silence = False
                obj._MustUse__used = True
                new_obj = obj.elaborate(platform)
            else:
                raise TypeError(f"Object {obj!r} is not an 'Elaboratable' nor 'Fragment'")
            if new_obj is obj:
                raise RecursionError(f"Object {obj!r} elaborates to itself")
            if new_obj is None and code is not None:
                warnings.warn_explicit(
                    message=".elaborate() returned None; missing return statement?",
                    category=UserWarning,
                    filename=code.co_filename,
                    lineno=code.co_firstlineno)
            origins.append(obj)
            obj = new_obj

    def __init__(self, *, src_loc=None):
        self.drivers = OrderedDict()
        self.statements = {}
        self.domains = OrderedDict()
        self.subfragments = []
        self.attrs = OrderedDict()
        self.generated = OrderedDict()
        self.src_loc = src_loc
        self.origins = None

    def add_driver(self, signal, domain="comb"):
        assert isinstance(domain, str)
        if domain not in self.drivers:
            self.drivers[domain] = _ast.SignalSet()
        self.drivers[domain].add(signal)

    def iter_drivers(self):
        for domain, signals in self.drivers.items():
            for signal in signals:
                yield domain, signal

    def iter_comb(self):
        if "comb" in self.drivers:
            yield from self.drivers["comb"]

    def iter_sync(self):
        for domain, signals in self.drivers.items():
            if domain == "comb":
                continue
            for signal in signals:
                yield domain, signal

    def add_domains(self, *domains):
        for domain in flatten(domains):
            assert isinstance(domain, _cd.ClockDomain)
            assert domain.name not in self.domains
            self.domains[domain.name] = domain

    def iter_domains(self):
        yield from self.domains

    def add_statements(self, domain, *stmts):
        assert isinstance(domain, str)
        for stmt in _ast.Statement.cast(stmts):
            stmt._MustUse__used = True
            self.statements.setdefault(domain, _ast._StatementList()).append(stmt)

    def add_subfragment(self, subfragment, name=None, *, src_loc=None):
        assert isinstance(subfragment, Fragment)
        self.subfragments.append((subfragment, name, src_loc))

    def find_subfragment(self, name_or_index):
        if isinstance(name_or_index, int):
            if name_or_index < len(self.subfragments):
                subfragment, name, src_loc = self.subfragments[name_or_index]
                return subfragment
            raise NameError(f"No subfragment at index #{name_or_index}")
        else:
            for subfragment, name, src_loc in self.subfragments:
                if name == name_or_index:
                    return subfragment
            raise NameError(f"No subfragment with name '{name_or_index}'")

    def find_generated(self, *path):
        if len(path) > 1:
            path_component, *path = path
            return self.find_subfragment(path_component).find_generated(*path)
        else:
            item, = path
            return self.generated[item]

    def elaborate(self, platform):
        return self

    def _propagate_domains_up(self, hierarchy=("top",)):
        from ._xfrm import DomainRenamer

        domain_subfrags = defaultdict(set)

        # For each domain defined by a subfragment, determine which subfragments define it.
        for i, (subfrag, name, src_loc) in enumerate(self.subfragments):
            # First, recurse into subfragments and let them propagate domains up as well.
            hier_name = name
            if hier_name is None:
                hier_name = f"<unnamed #{i}>"
            subfrag._propagate_domains_up(hierarchy + (hier_name,))

            # Second, classify subfragments by domains they define.
            for domain_name, domain in subfrag.domains.items():
                if domain.local:
                    continue
                domain_subfrags[domain_name].add((subfrag, name, src_loc, i))

        # For each domain defined by more than one subfragment, rename the domain in each
        # of the subfragments such that they no longer conflict.
        for domain_name, subfrags in domain_subfrags.items():
            if len(subfrags) == 1:
                continue

            names = [n for f, n, s, i in subfrags]
            if not all(names):
                names = sorted(f"<unnamed #{i}>" if n is None else f"'{n}'"
                               for f, n, s, i in subfrags)
                raise _cd.DomainError(
                    "Domain '{}' is defined by subfragments {} of fragment '{}'; it is necessary "
                    "to either rename subfragment domains explicitly, or give names to subfragments"
                    .format(domain_name, ", ".join(names), ".".join(hierarchy)))

            if len(names) != len(set(names)):
                names = sorted(f"#{i}" for f, n, s, i in subfrags)
                raise _cd.DomainError(
                    "Domain '{}' is defined by subfragments {} of fragment '{}', some of which "
                    "have identical names; it is necessary to either rename subfragment domains "
                    "explicitly, or give distinct names to subfragments"
                    .format(domain_name, ", ".join(names), ".".join(hierarchy)))

            for subfrag, name, src_loc, i in subfrags:
                domain_name_map = {domain_name: f"{name}_{domain_name}"}
                self.subfragments[i] = (DomainRenamer(domain_name_map)(subfrag), name, src_loc)

        # Finally, collect the (now unique) subfragment domains, and merge them into our domains.
        for subfrag, name, src_loc in self.subfragments:
            for domain_name, domain in subfrag.domains.items():
                if domain.local:
                    continue
                self.add_domains(domain)

    def _propagate_domains_down(self):
        # For each domain defined in this fragment, ensure it also exists in all subfragments.
        for subfrag, name, src_loc in self.subfragments:
            for domain in self.iter_domains():
                if domain in subfrag.domains:
                    assert self.domains[domain] is subfrag.domains[domain]
                else:
                    subfrag.add_domains(self.domains[domain])

            subfrag._propagate_domains_down()

    def _create_missing_domains(self, missing_domain, *, platform=None):
        from ._xfrm import DomainCollector

        collector = DomainCollector()
        collector(self)

        new_domains = []
        for domain_name in collector.used_domains - collector.defined_domains:
            if domain_name == "comb":
                continue
            value = missing_domain(domain_name)
            if value is None:
                raise _cd.DomainError(f"Domain '{domain_name}' is used but not defined")
            if type(value) is _cd.ClockDomain:
                self.add_domains(value)
                # And expose ports on the newly added clock domain, since it is added directly
                # and there was no chance to add any logic driving it.
                new_domains.append(value)
            else:
                new_fragment = Fragment.get(value, platform=platform)
                if domain_name not in new_fragment.domains:
                    defined = new_fragment.domains.keys()
                    raise _cd.DomainError(
                        "Fragment returned by missing domain callback does not define "
                        "requested domain '{}' (defines {})."
                        .format(domain_name, ", ".join(f"'{n}'" for n in defined)))
                self.add_subfragment(new_fragment, f"cd_{domain_name}")
                self.add_domains(new_fragment.domains.values())
        return new_domains

    def _propagate_domains(self, missing_domain, *, platform=None):
        self._propagate_domains_up()
        self._propagate_domains_down()
        new_domains = self._create_missing_domains(missing_domain, platform=platform)
        self._propagate_domains_down()
        return new_domains

    def _prepare_ports(self, ports):
        # Normalize ports to a list.
        new_ports = []
        if isinstance(ports, dict):
            for port_name, (signal, dir) in ports.items():
                new_ports.append((port_name, signal, dir))
        elif isinstance(ports, (list, tuple)):
            for port in ports:
                if isinstance(port, tuple):
                    port_name, signal, dir = port
                    new_ports.append((port_name, signal, dir))
                else:
                    new_ports.append((None, port, None))
        else:
            msg = f"`ports` must be a dict, a list or a tuple, not {ports!r}"
            if isinstance(ports, _ast.Value):
                msg += " (did you mean `ports=(<signal>,)`, rather than `ports=<signal>`?)"
            raise TypeError(msg)

        # Validate ports.
        prenamed_ports = set()
        for (port_name, signal, dir) in new_ports:
            if isinstance(port_name, str):
                if port_name in prenamed_ports:
                    raise TypeError(f"Duplicate port name {port_name!r}")
                else:
                    prenamed_ports.add(port_name)
            elif port_name is not None:
                raise TypeError(f"Port name must be a string, not {port_name!r}")
            if dir is not None and not isinstance(dir, PortDirection):
                raise TypeError(
                    f"Port direction must be a `PortDirection` instance or None, not {dir!r}")
            if not isinstance(signal, (_ast.Signal, _ast.ClockSignal, _ast.ResetSignal, _ast.IOPort)):
                raise TypeError(f"Only signals and IO ports may be added as ports, not {signal!r}")

        return new_ports

    def prepare(self, ports=(), *, hierarchy=("top",), missing_domain=lambda name: _cd.ClockDomain(name), propagate_domains=True):
        from ._xfrm import DomainLowerer

        ports = self._prepare_ports(ports)

        if propagate_domains:
            new_domains = self._propagate_domains(missing_domain)
            for domain in new_domains:
                ports.append((None, domain.clk, PortDirection.Input))
                if domain.rst is not None:
                    ports.append((None, domain.rst, PortDirection.Input))

        def resolve_signal(signal):
            if isinstance(signal, _ast.ClockSignal):
                domain = self.domains[signal.domain]
                return domain.clk
            elif isinstance(signal, _ast.ResetSignal):
                domain = self.domains[signal.domain]
                if domain.rst is None:
                    raise ValueError(f"Using ResetSignal for a reset-less domain {signal.domain}")
                return domain.rst
            else:
                return signal

        ports = [
            (name, resolve_signal(signal), dir)
            for name, signal, dir in ports
        ]

        fragment = DomainLowerer()(self)

        # Create design and let it do the rest.
        return Design(fragment, ports, hierarchy=hierarchy)


class Instance(Fragment):
    def __init__(self, type, *args, src_loc=None, src_loc_at=0, **kwargs):
        super().__init__(src_loc=src_loc or tracer.get_src_loc(src_loc_at))

        self.type        = type
        self.parameters  = OrderedDict()
        self.named_ports = OrderedDict()
        self.ports       = OrderedDict()

        for (kind, name, value) in args:
            if kind == "a":
                self.attrs[name] = value
            elif kind == "p":
                self.parameters[name] = value
            elif kind in ("i", "o", "io"):
                if kind == "io":
                    value = _ast.IOValue.cast(value)
                else:
                    if not isinstance(value, _ast.IOValue):
                        value = _ast.Value.cast(value)
                self.named_ports[name] = (value, kind)
                self.ports[name] = (value, kind)
            else:
                raise NameError("Instance argument {!r} should be a tuple (kind, name, value) "
                                "where kind is one of \"a\", \"p\", \"i\", \"o\", or \"io\""
                                .format((kind, name, value)))

        for kw, arg in kwargs.items():
            if kw.startswith("a_"):
                self.attrs[kw[2:]] = arg
            elif kw.startswith("p_"):
                self.parameters[kw[2:]] = arg
            elif kw.startswith("i_"):
                if not isinstance(arg, _ast.IOValue):
                    arg = _ast.Value.cast(arg)
                self.named_ports[kw[2:]] = (arg, "i")
                self.ports[kw[2:]] = (arg, "i")
            elif kw.startswith("o_"):
                if not isinstance(arg, _ast.IOValue):
                    arg = _ast.Value.cast(arg)
                self.named_ports[kw[2:]] = (arg, "o")
                self.ports[kw[2:]] = (arg, "o")
            elif kw.startswith("io_"):
                value = _ast.IOValue.cast(arg)
                self.named_ports[kw[3:]] = (value, "io")
                self.ports[kw[3:]] = (value, "io")
            else:
                raise NameError("Instance keyword argument {}={!r} does not start with one of "
                                "\"a_\", \"p_\", \"i_\", \"o_\", or \"io_\""
                                .format(kw, arg))


class IOBufferInstance(Fragment):
    def __init__(self, port, *, i=None, o=None, oe=None, src_loc_at=0, src_loc=None):
        super().__init__()

        self.port = _ast.IOValue.cast(port)
        if i is None:
            self.i = None
        else:
            self.i = _ast.Value.cast(i)
            if len(self.port) != len(self.i):
                raise ValueError(f"'port' length ({len(self.port)}) doesn't match 'i' length ({len(self.i)})")
        if o is None:
            if oe is not None:
                raise ValueError("'oe' must not be used if 'o' is not used")
            self.o = None
            self.oe = None
        else:
            self.o = _ast.Value.cast(o)
            if len(self.port) != len(self.o):
                raise ValueError(f"'port' length ({len(self.port)}) doesn't match 'o' length ({len(self.o)})")
            if oe is None:
                self.oe = _ast.Const(1)
            else:
                self.oe = _ast.Value.cast(oe)
                if len(self.oe) != 1:
                    raise ValueError(f"'oe' length ({len(self.oe)}) must be 1")

        self.src_loc = src_loc or tracer.get_src_loc(src_loc_at)


def _add_name(assigned_names, name):
    if name in assigned_names:
        name = f"{name}${len(assigned_names)}"
        assert name not in assigned_names
    assigned_names.add(name)
    return name


class DesignFragmentInfo:
    def __init__(self, parent, depth):
        self.parent = parent
        self.depth = depth
        self.signal_names = _ast.SignalDict()
        self.io_port_names = {}
        # Fixed up later.
        self.name: "tuple[str]" = ()
        self.assigned_names = set()
        # These two are used as sets, but are stored as dicts to ensure deterministic iteration order.
        self.used_signals = _ast.SignalDict()
        self.used_io_ports = {}


class Design:
    """Represents a design ready for simulation or netlist building.

    Returned by ``Fragment.prepare``."""

    def __init__(self, fragment: Fragment, ports, *, hierarchy):
        self.fragment = fragment
        self.ports = list(ports)
        self.hierarchy = hierarchy
        self.fragments: dict[Fragment, DesignFragmentInfo] = {}
        self.signal_lca = _ast.SignalDict()
        self._compute_fragment_depth_parent(fragment, None, 0)
        self._collect_used_signals(fragment)
        self._add_io_ports()
        self._assign_port_names()
        for name, conn, dir in self.ports:
            if isinstance(conn, _ast.IOPort):
                self._use_io_port(fragment, conn)
            else:
                self._use_signal(fragment, conn)
        self._assign_names(fragment, hierarchy)

    def _compute_fragment_depth_parent(self, fragment: Fragment, parent: "Fragment | None", depth: int):
        """Recursively computes every fragment's depth and parent."""
        self.fragments[fragment] = DesignFragmentInfo(parent, depth)
        for subfragment, _name, _src_loc in fragment.subfragments:
            self._compute_fragment_depth_parent(subfragment, fragment, depth + 1)

    def _use_signal(self, fragment: Fragment, signal: _ast.Signal):
        """Marks a signal as used in a given fragment.

        Also marks a signal as used if it has to be routed through a given fragment to get from
        one part of hierarchy to another.  For this purpose, the ``self.signal_lca`` dictionary
        is maintained: for every signal, it stores the topmost fragment in which it has been
        marked used so far.
        """
        if signal in self.fragments[fragment].used_signals:
            return
        self.fragments[fragment].used_signals[signal] = None
        if signal not in self.signal_lca:
            # First time we see a signal.
            self.signal_lca[signal] = fragment
            return
        # Signal already seen — go from current fragment to the LCA, marking everything along
        # the way as used.
        lca = self.signal_lca[signal]
        # First, go up from our fragment until it is no deeper than current LCA.
        while self.fragments[lca].depth < self.fragments[fragment].depth:
            fragment = self.fragments[fragment].parent
            # Early return if we reach a part of tree where the signal is already marked.
            if signal in self.fragments[fragment].used_signals:
                return
            self.fragments[fragment].used_signals[signal] = None
        # Second, go up from current LCA until it is no deeper than our fragment.
        while self.fragments[lca].depth > self.fragments[fragment].depth:
            lca = self.fragments[lca].parent
            self.fragments[lca].used_signals[signal] = None
        # Now, both fragments are at the same depth. Go up from both until the two paths meet.
        while fragment is not lca:
            lca = self.fragments[lca].parent
            self.fragments[lca].used_signals[signal] = None
            fragment = self.fragments[fragment].parent
            self.fragments[fragment].used_signals[signal] = None
        self.signal_lca[signal] = lca

    def _use_io_port(self, fragment: Fragment, port: _ast.IOPort):
        """Marks an IO port as used in a given fragment and all its ancestors."""
        frag_info = self.fragments[fragment]
        if port in frag_info.used_io_ports:
            return
        frag_info.used_io_ports[port] = None
        if frag_info.parent is not None:
            self._use_io_port(frag_info.parent, port)

    def _collect_used_signals(self, fragment: Fragment):
        """Collects used signals and IO ports for a fragment and all its subfragments."""
        from . import _mem
        if isinstance(fragment, _ir.Instance):
            for conn, kind in fragment.named_ports.values():
                if isinstance(conn, _ast.IOValue):
                    for port in conn._ioports():
                        self._use_io_port(fragment, port)
                elif isinstance(conn, _ast.Value):
                    for signal in conn._rhs_signals():
                        self._use_signal(fragment, signal)
                else:
                    assert False # :nocov:
        elif isinstance(fragment, _ir.IOBufferInstance):
            for port in fragment.port._ioports():
                self._use_io_port(fragment, port)
            if fragment.i is not None:
                for signal in fragment.i._rhs_signals():
                    self._use_signal(fragment, signal)
            if fragment.o is not None:
                for signal in fragment.o._rhs_signals():
                    self._use_signal(fragment, signal)
                for signal in fragment.oe._rhs_signals():
                    self._use_signal(fragment, signal)
        elif isinstance(fragment, _mem.MemoryInstance):
            for port in fragment._read_ports:
                for signal in port._addr._rhs_signals():
                    self._use_signal(fragment, signal)
                for signal in port._data._rhs_signals():
                    self._use_signal(fragment, signal)
                for signal in port._en._rhs_signals():
                    self._use_signal(fragment, signal)
                if port._domain != "comb":
                    domain = fragment.domains[port._domain]
                    self._use_signal(fragment, domain.clk)
                    if domain.rst is not None:
                        self._use_signal(fragment, domain.rst)
            for port in fragment._write_ports:
                for signal in port._addr._rhs_signals():
                    self._use_signal(fragment, signal)
                for signal in port._data._rhs_signals():
                    self._use_signal(fragment, signal)
                for signal in port._en._rhs_signals():
                    self._use_signal(fragment, signal)
                domain = fragment.domains[port._domain]
                self._use_signal(fragment, domain.clk)
                if domain.rst is not None:
                    self._use_signal(fragment, domain.rst)
        else:
            for domain_name, statements in fragment.statements.items():
                if domain_name != "comb":
                    domain = fragment.domains[domain_name]
                    self._use_signal(fragment, domain.clk)
                    if domain.rst is not None:
                        self._use_signal(fragment, domain.rst)
                for statement in statements:
                    for signal in statement._lhs_signals() | statement._rhs_signals():
                        if not isinstance(signal, (_ast.ClockSignal, _ast.ResetSignal)):
                            self._use_signal(fragment, signal)
            for subfragment, _name, _src_loc in fragment.subfragments:
                self._collect_used_signals(subfragment)

    def _add_io_ports(self):
        """Adds all used IO ports to our list of top-level ports, if they aren't there already."""
        io_ports = {conn for name, conn, dir in self.ports if isinstance(conn, _ast.IOPort)}
        for port in self.fragments[self.fragment].used_io_ports:
            if port not in io_ports:
                self.ports.append((None, port, None))

    def _assign_port_names(self):
        """Assigns names to all ports that haven't been explicitly named."""
        new_ports = []
        assigned_names = {name for name, conn, dir in self.ports if name is not None}
        for name, conn, dir in self.ports:
            if name is None:
                name = _add_name(assigned_names, conn.name)
                assigned_names.add(name)
            new_ports.append((name, conn, dir))
        self.ports = new_ports

    def _assign_names(self, fragment: Fragment, hierarchy: "tuple[str]"):
        """Assign names to signals and IO ports used in a given fragment, as well as its
        subfragments.

        The signal mapping is set in ``self.signal_names``, and the IO port mapping is set in
        ``self.io_port_names``.  Because names are deduplicated using local information only,
        the same signal used in a different fragment may get a different name.

        Subfragments may not necessarily have a name. This method assigns every such subfragment
        a name, ``U$<number>``, where ``<number>`` is based on its location in the hierarchy.

        Subfragment names may collide with signal names safely in Amaranth, but this may confuse
        backends. This method assigns every such subfragment a new name.

        Arguments
        ---------
        hierarchy : tuple of str
            Name of this fragment.
        """

        frag_info = self.fragments[fragment]
        frag_info.name = hierarchy

        if fragment is self.fragment:
            # Reserve names for top-level ports. If equal to the signal name, let the signal share it.
            for name, conn, _dir in self.ports:
                frag_info.assigned_names.add(name)
                if isinstance(conn, _ast.Signal) and conn.name == name:
                    frag_info.signal_names[conn] = name
                elif isinstance(conn, _ast.IOPort) and conn.name == name:
                    frag_info.io_port_names[conn] = name

        for signal in frag_info.used_signals:
            if signal not in frag_info.signal_names:
                frag_info.signal_names[signal] = _add_name(frag_info.assigned_names, signal.name)
        for port in frag_info.used_io_ports:
            if port not in frag_info.io_port_names:
                frag_info.io_port_names[port] = _add_name(frag_info.assigned_names, port.name)

        for subfragment_index, (subfragment, subfragment_name, subfragment_src_loc) in enumerate(fragment.subfragments):
            if subfragment_name is None:
                subfragment_name = f"U${subfragment_index}"
            subfragment_name = _add_name(frag_info.assigned_names, subfragment_name)
            self._assign_names(subfragment, hierarchy=(*hierarchy, subfragment_name))


